DO $report$
DECLARE
  t record;
BEGIN
  FOR t IN SELECT x FROM unnest(ARRAY['activity_logs', 'approval_history', 'branches', 'business_settings', 'businesses', 'categories', 'customer_activity', 'customer_notes', 'customer_segments', 'customer_tag_assignments', 'customers', 'expense_attachments', 'expense_categories', 'expenses', 'inventory', 'notifications', 'permissions', 'products', 'profiles', 'purchase_order_items', 'purchase_orders', 'purchase_payments', 'purchase_return_items', 'purchase_returns', 'recurring_expenses', 'role_permissions', 'roles', 'sale_items', 'sale_return_items', 'sale_returns', 'sales', 'sales_targets', 'stock_movements', 'supplier_notes', 'suppliers', 'tags']) x LOOP
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = t.x) THEN
      RAISE NOTICE '[present]   %', t.x;
    ELSE
      RAISE NOTICE '[MISSING]   %', t.x;
    END IF;
  END LOOP;
END
$report$;


-- ---------------------------------------------------------------------------
-- 0.5 Repair duplicates (system roles) left by earlier non-idempotent runs
-- ---------------------------------------------------------------------------
DO $dedup$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'roles'
  ) THEN
    -- Keep only the oldest row per (name, business_id); drop all newer copies
    DELETE FROM public.roles a
    WHERE a.is_system = true
      AND EXISTS (
        SELECT 1 FROM public.roles b
        WHERE b.name = a.name
          AND b.is_system = true
          AND b.business_id IS NOT DISTINCT FROM a.business_id
          AND (b.created_at, b.id) < (a.created_at, a.id)
      );
  END IF;
END
$dedup$;


