BEGIN
  INSERT INTO public.roles (business_id, name, description, is_system)
  SELECT v.*
  FROM (VALUES
(NULL::uuid, ''super_admin'', ''Full platform access'', true),
  (NULL::uuid, ''business_owner'', ''Full access to own business'', true),
  (NULL::uuid, ''branch_manager'', ''Manage a single branch'', true),
  (NULL::uuid, ''cashier'', ''Process sales at POS'', true),
  (NULL::uuid, ''marketing_manager'', ''Manage marketing campaigns'', true),
  (NULL::uuid, ''inventory_manager'', ''Manage products and inventory'', true),
  (NULL::uuid, ''accountant'', ''Manage expenses and view reports'', true),
  (NULL::uuid, ''staff'', ''Basic staff access'', true)
  ) AS v(business_id, name, description, is_system)
  WHERE NOT EXISTS (
    SELECT 1 FROM public.roles r
    WHERE r.name = v.name
      AND r.is_system = true
      AND r.business_id IS NOT DISTINCT FROM v.business_id
  );
END
$seed$';
