EXCEPTION WHEN OTHERS THEN
  IF SQLSTATE IN ('42P07','42710','42701','23505','0A000','428C9') THEN
    RAISE NOTICE '[skip: already present] %', LEFT(SQLERRM, 90);
  ELSE
    RAISE;
  END IF;
END
$setup$;

DO $setup$
BEGIN
  EXECUTE '-- RLS policies call auth.uid(); make sure authenticated can use the schema
-- (Supabase platform defaults cover this; guarded so plain Postgres is fine).
DO $authgrants$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.schemata WHERE schema_name = ''auth'') THEN
    GRANT USAGE ON SCHEMA auth TO authenticated;
  END IF;
END
$authgrants$';
EXCEPTION WHEN OTHERS THEN
  IF SQLSTATE IN ('42P07','42710','42701','23505','0A000','428C9') THEN
    RAISE NOTICE '[skip: already present] %', LEFT(SQLERRM, 90);
  ELSE
    RAISE;
  END IF;
END
$setup$;

DO $setup$
BEGIN
  EXECUTE 'DO $grants$
DECLARE
  rec record;
BEGIN
  FOR rec IN
    SELECT c.relname
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = ''public'' AND c.relkind = ''r''
  LOOP
    EXECUTE format(
      ''GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated'',
      rec.relname
    );
  END LOOP;
END
$grants$';
EXCEPTION WHEN OTHERS THEN
  IF SQLSTATE IN ('42P07','42710','42701','23505','0A000','428C9') THEN
    RAISE NOTICE '[skip: already present] %', LEFT(SQLERRM, 90);
  ELSE
    RAISE;
  END IF;
END
$setup$;

