-- ---------------------------------------------------------------------------
-- Final report (AFTER applying)
-- ---------------------------------------------------------------------------
DO $report$
DECLARE
  t record;
  n bigint;
BEGIN
  FOR t IN SELECT x FROM unnest(ARRAY['activity_logs', 'approval_history', 'branches', 'business_settings', 'businesses', 'categories', 'customer_activity', 'customer_notes', 'customer_segments', 'customer_tag_assignments', 'customers', 'expense_attachments', 'expense_categories', 'expenses', 'inventory', 'notifications', 'permissions', 'products', 'profiles', 'purchase_order_items', 'purchase_orders', 'purchase_payments', 'purchase_return_items', 'purchase_returns', 'recurring_expenses', 'role_permissions', 'roles', 'sale_items', 'sale_return_items', 'sale_returns', 'sales', 'sales_targets', 'stock_movements', 'supplier_notes', 'suppliers', 'tags']) x LOOP
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = t.x) THEN
      RAISE EXCEPTION 'Table % is still MISSING after setup — check the errors above', t.x;
    END IF;
  END LOOP;
  SELECT count(*) INTO n FROM public.roles WHERE is_system = true;
  RAISE NOTICE 'system roles seeded: %', n;
  SELECT count(*) INTO n FROM public.permissions;
  RAISE NOTICE 'permissions seeded: %', n;
  SELECT count(*) INTO n FROM public.role_permissions;
  RAISE NOTICE 'role_permission links: %', n;
  RAISE NOTICE '=== LIVE SETUP COMPLETE: all % tables present ===', 36;
END
$report$;
